package jrsonnet

// withThread runs fn on the VM's dedicated OS thread and waits for it to
// complete. Returns ErrVMClosed if the VM has been closed.
//
// All FFI calls into jrsonnet must go through this function so they run on
// the thread that owns the VM's jrsonnet TLS (interner pool, gcmodule state,
// and the thread_local IStr caches generated by jrsonnet-macros).
func (v *VM) withThread(fn func()) error {
	v.mu.Lock()
	if v.closed {
		v.mu.Unlock()
		return ErrVMClosed
	}

	done := make(chan struct{})
	task := vmTask{fn: fn, done: done}

	// Send while holding the mutex to guarantee we never send on a closed
	// channel: Close() acquires mu before closing v.tasks. The send blocks
	// until the dedicated goroutine accepts the task, which provides the
	// per-VM serialisation that callers rely on.
	v.tasks <- task
	v.mu.Unlock()

	<-done
	return nil
}
